using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using OrcaFacil.Application.Abstractions;using OrcaFacil.Domain.Entities;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.Services;[Authorize]public sealed class CreateModel(OrcaFacilDbContext db,ICurrentAccountService account):PageModel{[BindProperty]public ServiceFormModel Input{get;set;}=new();public void OnGet(){}public async Task<IActionResult> OnPostAsync(CancellationToken ct){if(account.AccountId is not Guid accountId)return Forbid();if(!ServiceFormModel.Units.ContainsKey(Input.UnitCode))ModelState.AddModelError("Input.UnitCode","Unidade inválida.");if(!ModelState.IsValid)return Page();db.ServiceCatalogItems.Add(new ServiceCatalogItem{AccountId=accountId,Name=Input.Name.Trim(),Code=string.IsNullOrWhiteSpace(Input.Code)?null:Input.Code.Trim(),Description=Input.Description?.Trim(),UnitCode=Input.UnitCode,StandardPrice=Input.StandardPrice,EstimatedCost=Input.EstimatedCost,SuggestedDurationMinutes=Input.SuggestedDurationMinutes,InternalNotes=Input.InternalNotes?.Trim(),IsFavorite=Input.IsFavorite,IsActive=Input.IsActive});await db.SaveChangesAsync(ct);TempData["Success"]="Serviço adicionado ao catálogo.";return RedirectToPage("Index");}}
